from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.ta_matchers.matchers import Any, Contains, Omit
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageDetail


nr_pdcp_bearer = \
    Any({
        'DRB-ToAddMod': Any({
            'pdcp-Config': Any({
                'drb': Any({
                    'discardTimer': 'ms300',
                    'pdcp-SN-SizeUL': 'len18bits',
                    'pdcp-SN-SizeDL': 'len18bits',
                    'headerCompression': Any({'notUsed': None}),
                }),
                't-Reordering': 'ms300'
            })
        })
    })


class nr_bearers(ExpectationsManager):
    def with_nr_pdcp_bearer(self):
        self.append_expectation(MessageDetail('radioResourceConfigDedicated.drb-ToAddModList', Any({'pdcp-Config': Omit()}), Contains))
        self.append_expectation(MessageDetail('nr-RadioBearerConfig1-r15.RadioBearerConfig.drb-ToAddModList', nr_pdcp_bearer, Contains))
